1	#!/usr/bin/env node
2	// qa/axe-portal.mjs – Barrierefreiheit (axe-core) auf Portalseiten MIT Demo-Login (Paket UIUX, Plattform-Armee)
3	//
4	//   node qa/axe-portal.mjs                       prüfen gegen qa/axe-portal-baseline.json (Gate)
5	//   node qa/axe-portal.mjs --baseline-schreiben  heutigen Stand als Baseline festhalten
6	//   node qa/axe-portal.mjs --breiten 1440,390    zusätzlich mobil (Standard: 1440,390)
7	//   node qa/axe-portal.mjs --rollen admin,investor   nur diese Rollen
8	//   node qa/axe-portal.mjs --shots <ordner>      Screenshot je Prüfung (Belege vorher/nachher)
9	//   node qa/axe-portal.mjs --json qa/out/axe-portal.json
10	//
11	// Läuft NUR gegen das lokale Demo-Backend (Demo-Konten aus src/lib/plattform/backend/demo/seed.js).
12	// Anmeldung wie qa/e2e/*.e2e.mjs über POST /api/auth/login im Browser-Kontext (Cookie geteilt).
13	// Zusätzlich je Seite drei Strukturprüfungen (UX-Audit Q8/Q10): genau eine h1, ein main-Landmark,
14	// kein horizontaler Überlauf bei 390 px.
15	// Gate-Logik wie qa/axe.mjs (Ratsche): neue serious/critical-Regel = Fehler, mehr Elemente = Warnung.
16	
17	import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
18	import { dirname, join, resolve } from "node:path";
19	import { fileURLToPath } from "node:url";
20	import { axePfad, lade, ladePlaywright, neuerKontext, serverErreichbar, zeit, BASIS } from "./browser.mjs";
21	
22	const HIER = dirname(fileURLToPath(import.meta.url));
23	const BASELINE = join(HIER, "axe-portal-baseline.json");
24	const TAGS = ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"];
25	const SCHWER = new Set(["serious", "critical"]);
26	const PASSWORT = process.env.PLATTFORM_DEMO_PASSWORT || "Demo-2026!";
27	
28	// Kernseiten je Rolle: Startübersicht + die Hauptarbeitswege (UX-Audit „12 Kernwege“).
29	// Querschnittsseiten (Profil, Sicherheit, Dokumente …) nur einmal (Rolle flaeche), damit der Lauf schnell bleibt.
30	export const ROLLEN = {
31	  flaeche: {
32	    email: "flaeche@example.com",
33	    seiten: ["/portal", "/portal/anfragen", "/portal/flaechen", "/portal/pachtvertraege", "/portal/entwicklung", "/portal/abrechnungen", "/portal/verifizierung", "/portal/dokumente", "/portal/profil", "/portal/sicherheit", "/portal/support", "/portal/benachrichtigungen", "/portal/nachrichten", "/portal/termine"],
34	  },
35	  investor: { email: "investor@example.com", seiten: ["/portal", "/portal/boerse", "/portal/pipeline", "/portal/portfolio", "/portal/finanzierung", "/portal/closing"] },
36	  anbieter: { email: "anbieter@example.com", seiten: ["/portal", "/portal/projekte"] },
37	  unternehmen: { email: "unternehmen@example.com", seiten: ["/portal", "/portal/anlagen", "/portal/energie", "/portal/energie/beschaffung", "/portal/anliegen"] },
38	  mitglied: { email: "mitglied@example.com", seiten: ["/portal", "/portal/beteiligung", "/portal/eg"] },
39	  kommune: { email: "kommune@example.com", seiten: ["/portal", "/portal/kommune"] },
40	  bank: { email: "bank@example.com", seiten: ["/portal", "/portal/bank"] },
41	  gutachter: { email: "gutachter@example.com", seiten: ["/portal", "/portal/gutachter"] },
42	  lieferant: { email: "lieferant@example.com", seiten: ["/portal", "/portal/ausschreibungen"] },
43	  admin: {
44	    email: "admin@example.com",
45	    seiten: ["/portal/admin", "/portal/admin/aufgaben", "/portal/admin/vorgaenge", "/portal/admin/leads", "/portal/admin/flaechen", "/portal/admin/projekte", "/portal/admin/interessen", "/portal/admin/dealroom", "/portal/admin/entwicklung", "/portal/admin/anlagen", "/portal/admin/pachtakten", "/portal/organisation"],
46	  },
47	};
48	
49	function argumente(argv) {
50	  const a = { schreiben: false, breiten: [1440, 390], rollen: Object.keys(ROLLEN), json: null, shots: null };
51	  for (let i = 0; i < argv.length; i++) {
52	    const k = argv[i];
53	    if (k === "--baseline-schreiben") a.schreiben = true;
54	    else if (k === "--breiten") a.breiten = argv[++i].split(",").map(Number);
55	    else if (k === "--rollen") a.rollen = argv[++i].split(",");
56	    else if (k === "--json") a.json = argv[++i];
57	    else if (k === "--shots") a.shots = argv[++i];
58	  }
59	  return a;
60	}
