62	/** Demo-Anmeldung im Kontext (Cookie wird mit den Seiten geteilt); wirft bei Fehlschlag. */
63	async function anmelden(ctx, email) {
64	  const r = await ctx.request.post(`${BASIS}/api/auth/login`, {
65	    headers: { Origin: BASIS, "Content-Type": "application/json" },
66	    data: { email, passwort: PASSWORT },
67	  });
68	  if (r.status() !== 200) throw new Error(`Demo-Anmeldung ${email}: HTTP ${r.status()}`);
69	}
70	
71	async function pruefeSeite(page, axeQuelle, pfad, breite, shots, schluessel) {
72	  let status = await lade(page, pfad, { warten: 1500 });
73	  if (status !== 200) {
74	    await page.waitForTimeout(8000);
75	    status = await lade(page, pfad, { warten: 1500 });
76	  }
77	  if (status !== 200) return { status, fehler: `HTTP ${status}` };
78	  // Auf eingeloggten Zustand prüfen: Portalseiten leiten ohne Sitzung auf /login um
79	  if (/\/login/.test(page.url())) return { status, fehler: "nicht angemeldet (Umleitung auf /login)" };
80	  if (shots) {
81	    mkdirSync(shots, { recursive: true });
82	    const name = schluessel.replace(/[^a-z0-9@-]+/gi, "_").replace(/^_+|_+$/g, "");
83	    await page.screenshot({ path: join(shots, `${name}.png`), fullPage: breite === 390 }).catch(() => {});
84	  }
85	  await page.addScriptTag({ content: axeQuelle });
86	  const erg = await page.evaluate(async (tags) => {
87	    const r = await window.axe.run(document, { runOnly: { type: "tag", values: tags }, resultTypes: ["violations"] });
88	    const struktur = [];
89	    const h1 = document.querySelectorAll("h1").length;
90	    if (h1 !== 1) struktur.push({ id: "struktur-h1", impact: "moderate", hilfe: `Seite hat ${h1} h1-Überschriften (erwartet: 1)`, knoten: Math.max(h1, 1), ziele: ["h1"] });
91	    if (!document.querySelector("main")) struktur.push({ id: "struktur-main", impact: "moderate", hilfe: "Kein <main>-Landmark", knoten: 1, ziele: ["body"] });
92	    const ueberlauf = document.documentElement.scrollWidth - document.documentElement.clientWidth;
93	    if (ueberlauf > 8) struktur.push({ id: "struktur-ueberlauf", impact: "serious", hilfe: `Horizontaler Überlauf ${ueberlauf}px`, knoten: 1, ziele: ["html"] });
94	    return r.violations
95	      .map((v) => ({ id: v.id, impact: v.impact, hilfe: v.help, knoten: v.nodes.length, ziele: v.nodes.slice(0, 3).map((n) => n.target.join(" ")) }))
96	      .concat(struktur);
97	  }, TAGS);
98	  return { status, verstoesse: erg };
99	}
100	
101	function bewerte(ergebnisse, baseline) {
102	  const fehler = [];
103	  const warnungen = [];
104	  for (const [schluessel, r] of Object.entries(ergebnisse)) {
105	    if (r.fehler) {
106	      fehler.push(`${schluessel}: Seite nicht prüfbar (${r.fehler})`);
107	      continue;
108	    }
109	    const basis = baseline[schluessel] || {};
110	    for (const v of r.verstoesse) {
111	      const alt = basis[v.id];
112	      if (alt === undefined) {
113	        (SCHWER.has(v.impact) ? fehler : warnungen).push(`${schluessel}: neue Regel ${v.id} (${v.impact}, ${v.knoten}×) – ${v.hilfe} → ${v.ziele.join(" | ")}`);
114	      } else if (v.knoten > alt) {
115	        warnungen.push(`${schluessel}: ${v.id} (${v.impact}) ${alt} → ${v.knoten} Elemente`);
116	      }
117	    }
118	  }
119	  return { fehler, warnungen };
120	}
121	
122	export async function laufAxePortal(opt) {
123	  const start = Date.now();
124	  const pw = await ladePlaywright();
125	  if (!pw) throw new Error("Playwright nicht gefunden (PLAYWRIGHT_PFAD setzen, siehe qa/README.md)");
126	  const axe = axePfad();
127	  if (!axe) throw new Error("axe-core nicht gefunden");
128	  if (!(await serverErreichbar())) throw new Error("Dev-Server nicht erreichbar (npm run dev, Port 3100)");
129	  const axeQuelle = readFileSync(axe, "utf8");
130	  const browser = await pw.chromium.launch();
131	  const ergebnisse = {};
132	  try {
133	    for (const breite of opt.breiten) {
134	      for (const rolle of opt.rollen) {
135	        const def = ROLLEN[rolle];
136	        if (!def) {
137	          console.error(`  Rolle unbekannt: ${rolle}`);
138	          continue;
139	        }
140	        const ctx = await neuerKontext(browser, { breite });
141	        try {
142	          await anmelden(ctx, def.email);
143	          const page = await ctx.newPage();
144	          // Mobil nur Startübersicht + die zwei wichtigsten Arbeitsseiten (Laufzeit), Desktop alles
145	          const seiten = breite === 1440 ? def.seiten : def.seiten.slice(0, 3);
146	          for (const pfad of seiten) {
147	            const t = Date.now();
148	            const schluessel = `${rolle} ${pfad}${breite === 1440 ? "" : ` @${breite}`}`;
149	            ergebnisse[schluessel] = await pruefeSeite(page, axeQuelle, pfad, breite, opt.shots, schluessel).catch((e) => ({ status: 0, fehler: String(e).split(/\r?\n/)[0].slice(0, 200) }));
150	            const r = ergebnisse[schluessel];
151	            const s = r.verstoesse ? r.verstoesse.filter((v) => SCHWER.has(v.impact)).length : "?";
152	            console.log(`  ${schluessel.padEnd(44)} ${r.fehler ? "FEHLER " + r.fehler : `${r.verstoesse.length} Regeln verletzt (${s} serious/critical)`}  ${zeit(t)}`);
153	          }
154	        } catch (e) {
155	          ergebnisse[`${rolle} (Anmeldung)${breite === 1440 ? "" : ` @${breite}`}`] = { status: 0, fehler: String(e.message || e).slice(0, 200) };
156	          console.log(`  ${rolle}: FEHLER ${e.message || e}`);
157	        } finally {
158	          await ctx.close();
159	        }
160	      }
161	    }
162	  } finally {
163	    await browser.close();
164	  }
165	  return { ergebnisse, dauer: zeit(start) };
166	}
167	
168	if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
169	  const opt = argumente(process.argv.slice(2));
170	  try {
171	    const { ergebnisse, dauer } = await laufAxePortal(opt);
172	    if (opt.json) {
173	      mkdirSync(dirname(resolve(opt.json)), { recursive: true });
174	      writeFileSync(opt.json, JSON.stringify(ergebnisse, null, 1), "utf8");
175	    }
176	    const gesamt = Object.values(ergebnisse).flatMap((r) => r.verstoesse || []);
177	    const schwer = gesamt.filter((v) => SCHWER.has(v.impact));
178	    console.log(`axe-portal: ${Object.keys(ergebnisse).length} Prüfungen in ${dauer}; ${gesamt.length} Regelverstöße, davon ${schwer.length} serious/critical (${schwer.reduce((s, v) => s + v.knoten, 0)} Elemente)`);
179	    if (opt.schreiben) {
180	      const baseline = {};
181	      for (const [k, r] of Object.entries(ergebnisse)) {
182	        if (r.fehler) {
183	          console.error(`Baseline NICHT geschrieben: ${k} nicht prüfbar (${r.fehler})`);
184	          process.exit(1);
185	        }
186	        baseline[k] = Object.fromEntries(r.verstoesse.map((v) => [v.id, v.knoten]));
187	      }
188	      writeFileSync(BASELINE, JSON.stringify({ _hinweis: "Altlasten-Stand für die axe-Ratsche auf Portalseiten (qa/axe-portal.mjs). Nur verkleinern; Ziel: leer.", _stand: new Date().toISOString().slice(0, 10), ...baseline }, null, 1) + "\n", "utf8");
189	      console.log(`Baseline geschrieben: ${BASELINE}`);
190	    } else {
191	      const roh = existsSync(BASELINE) ? JSON.parse(readFileSync(BASELINE, "utf8")) : {};
192	      const { fehler, warnungen } = bewerte(ergebnisse, roh);
193	      warnungen.forEach((w) => console.log(`  ! ${w}`));
194	      fehler.forEach((f) => console.log(`  ✗ ${f}`));
195	      for (const [k, regeln] of Object.entries(roh)) {
196	        if (k.startsWith("_") || !ergebnisse[k]?.verstoesse) continue;
197	        const jetzt = new Set(ergebnisse[k].verstoesse.map((v) => v.id));
198	        const weg = Object.keys(regeln).filter((id) => !jetzt.has(id));
199	        if (weg.length) console.log(`  ✓ ${k}: behoben ${weg.join(", ")} – Baseline verkleinern (--baseline-schreiben)`);
200	      }
201	      if (fehler.length) process.exitCode = 1;
202	    }
203	  } catch (e) {
204	    console.error(`axe-portal: ${e.message}`);
205	    process.exitCode = 1;
206	  }
207	}
