1	// Tastaturmuster für ARIA-Tablisten (Paket UIUX, Plattform-Armee):
2	// Pfeil links/rechts wechselt den Reiter, Pos1/Ende springt an Anfang/Ende (WAI-ARIA APG „Tabs“).
3	// Nutzung: <div role="tablist" onKeyDown={tabTasten} …> mit <button role="tab">-Kindern.
4	// Die Knöpfe bleiben bewusst alle in der Tab-Reihenfolge (kein Roving-Tabindex nötig);
5	// der Helfer ergänzt nur die erwartete Pfeiltasten-Bedienung und aktiviert den Ziel-Reiter.
6	
7	export function tabTasten(e) {
8	  const tabs = Array.from(e.currentTarget.querySelectorAll('[role="tab"]')).filter((t) => !t.disabled);
9	  const i = tabs.indexOf(document.activeElement);
10	  if (i < 0 || tabs.length < 2) return;
11	  let ziel = null;
12	  if (e.key === "ArrowRight") ziel = tabs[(i + 1) % tabs.length];
13	  else if (e.key === "ArrowLeft") ziel = tabs[(i - 1 + tabs.length) % tabs.length];
14	  else if (e.key === "Home") ziel = tabs[0];
15	  else if (e.key === "End") ziel = tabs[tabs.length - 1];
16	  if (ziel) {
17	    e.preventDefault();
18	    ziel.focus();
19	    ziel.click();
20	  }
21	}
