1	"use client";
2	
3	// Auswahl freier Zeitfenster (Woche für Woche). Lädt /api/portal/termine/slots – öffentlich für öffentliche Terminarten.
4	// Zeiten in Europe/Vienna. Tastatur: Pfeile/Tab über die Zeit-Buttons, Auswahl mit Enter/Leertaste.
5	
6	import { useEffect, useMemo, useState } from "react";
7	import { ChevronLeft, ChevronRight, Loader2 } from "lucide-react";
8	import { cn } from "@/components/ui/cn";
9	import { TZ, heuteTag, tagPlus } from "@/lib/plattform/termine";
10	import { useSprache } from "@/components/Sprache/SpracheKontext";
11	
12	const LOCALE = { de: "de-DE", en: "en-GB" };
13	const tagTextIn = (tag, l = "de") => new Date(`${tag}T12:00:00Z`).toLocaleDateString(LOCALE[l] || LOCALE.de, { weekday: "short", day: "2-digit", month: l === "en" ? "short" : "2-digit", timeZone: "UTC" });
14	const zeitIn = (iso, l = "de") => new Date(iso).toLocaleTimeString(LOCALE[l] || LOCALE.de, { hour: "2-digit", minute: "2-digit", timeZone: TZ });
15	const tagVon = (iso) => new Date(iso).toLocaleDateString("sv-SE", { timeZone: TZ });
16	
17	export default function SlotAuswahl({ art, gewaehlt, onWahl, mitarbeiterId = "", tage = 7, dunkel = false }) {
18	  const sprache = useSprache();
19	  const en = sprache === "en";
20	  const tagText = (tag) => tagTextIn(tag, sprache);
21	  const zeit = (iso) => zeitIn(iso, sprache);
22	  const [von, setVon] = useState(() => heuteTag());
23	  const [daten, setDaten] = useState({ slots: [], laden: true, fehler: "" });
24	
25	  useEffect(() => {
26	    let aktiv = true;
27	    setDaten((d) => ({ ...d, laden: true, fehler: "" }));
28	    const bis = tagPlus(von, tage - 1);
29	    fetch(`/api/portal/termine/slots?art=${encodeURIComponent(art)}&von=${von}&bis=${bis}${mitarbeiterId ? `&mitarbeiter=${mitarbeiterId}` : ""}`, { credentials: "same-origin", cache: "no-store" })
30	      .then((r) => r.json().then((j) => ({ ok: r.ok, j })))
31	      .then(({ ok, j }) => aktiv && setDaten({ slots: ok ? j.slots || [] : [], laden: false, fehler: ok ? "" : j.error || (en ? "Appointments could not be loaded." : "Termine konnten nicht geladen werden.") }))
32	      .catch(() => aktiv && setDaten({ slots: [], laden: false, fehler: en ? "No connection." : "Keine Verbindung." }));
33	    return () => {
34	      aktiv = false;
35	    };
36	  }, [art, von, tage, mitarbeiterId, en]);
37	
38	  const jeTag = useMemo(() => {
39	    const m = new Map();
40	    for (let i = 0; i < tage; i++) m.set(tagPlus(von, i), []);
41	    for (const s of daten.slots) m.get(tagVon(s.start))?.push(s);
42	    return [...m.entries()];
43	  }, [daten.slots, von, tage]);
44	
45	  const heute = heuteTag();
46	  const maxVon = tagPlus(heute, 42 - tage);
47	
48	  return (
49	    <div className="min-w-0">
50	      <div className="mb-3 flex items-center justify-between gap-2">
51	        <button type="button" onClick={() => setVon((v) => (tagPlus(v, -tage) < heute ? heute : tagPlus(v, -tage)))} disabled={von <= heute} className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full ring-1 ring-inset disabled:opacity-30", dunkel ? "text-white ring-white/30 hover:bg-white/10" : "text-ink-700 ring-ink-200 hover:bg-ink-50")} aria-label={en ? "Earlier appointments" : "Frühere Termine"}>
52	          <ChevronLeft className="h-5 w-5" />
53	        </button>
54	        <p className={cn("text-[14px] font-semibold", dunkel ? "text-white" : "text-ink-900")} aria-live="polite">
55	          {tagText(von)} – {tagText(tagPlus(von, tage - 1))}
56	        </p>
57	        <button type="button" onClick={() => setVon((v) => (tagPlus(v, tage) > maxVon ? maxVon : tagPlus(v, tage)))} disabled={von >= maxVon} className={cn("inline-flex h-10 w-10 items-center justify-center rounded-full ring-1 ring-inset disabled:opacity-30", dunkel ? "text-white ring-white/30 hover:bg-white/10" : "text-ink-700 ring-ink-200 hover:bg-ink-50")} aria-label={en ? "Later appointments" : "Spätere Termine"}>
58	          <ChevronRight className="h-5 w-5" />
59	        </button>
60	      </div>
61	      {daten.fehler && <p role="alert" className="mb-3 rounded-xl bg-danger-50 px-4 py-3 text-[14px] text-danger-800 ring-1 ring-danger-200">{daten.fehler}</p>}
62	      {/* Laden: nicht per Deckkraft dimmen – das drückte die Tagesbeschriftungen unter 4,5:1 Kontrast
63	          (axe-portal, WCAG 1.4.3). Spinner + aria-busy zeigen den Zustand, Klicks sind gesperrt. */}
64	      <div className={cn("relative grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-7", daten.laden && "pointer-events-none select-none")} aria-busy={daten.laden}>
65	        {daten.laden && <Loader2 aria-hidden="true" className="absolute left-1/2 top-6 h-6 w-6 -translate-x-1/2 animate-spin text-ov-600" />}
66	        {jeTag.map(([tag, liste]) => (
67	          <div key={tag} className={cn("min-w-0 rounded-2xl p-2.5 ring-1 ring-inset", dunkel ? "bg-white/5 ring-white/10" : "bg-ink-50/60 ring-ink-100")}>
68	            <p className={cn("mb-2 text-center text-[12.5px] font-semibold", dunkel ? "text-white/80" : "text-ink-600")}>{tagText(tag)}</p>
69	            {liste.length ? (
70	              <ul className="flex flex-col gap-1.5" aria-label={en ? `Free times on ${tagText(tag)}` : `Freie Zeiten am ${tagText(tag)}`}>
71	                {liste.map((s) => {
72	                  const aktiv = gewaehlt?.start === s.start;
73	                  return (
74	                    <li key={s.start}>
75	                      <button
76	                        type="button"
77	                        onClick={() => onWahl?.(s)}
78	                        aria-pressed={aktiv}
79	                        className={cn(
80	                          "ov-num w-full rounded-full px-2 py-1.5 text-[13.5px] font-semibold ring-1 ring-inset transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500",
81	                          aktiv ? "bg-ov-600 text-white ring-ov-600" : dunkel ? "bg-white/10 text-white ring-white/20 hover:bg-white/20" : "bg-white text-ink-800 ring-ink-200 hover:ring-ov-400"
82	                        )}
83	                      >
84	                        {zeit(s.start)}
85	                      </button>
86	                    </li>
87	                  );
88	                })}
89	              </ul>
90	            ) : (
91	              <p className={cn("py-2 text-center text-[12.5px]", dunkel ? "text-white/40" : "text-ink-400")}>–</p>
92	            )}
93	          </div>
94	        ))}
95	      </div>
96	      {!daten.laden && !daten.slots.length && !daten.fehler && <p className={cn("mt-3 text-[13.5px]", dunkel ? "text-white/70" : "text-ink-500")}>{en ? "Nothing is free this week – please browse on." : "In dieser Woche ist nichts mehr frei – bitte blättern Sie weiter."}</p>}
97	    </div>
98	  );
99	}
